from typing import List


def corporate_ladder(pair: List[str], pairs: List[List[str]]) -> int:
    manager = {emp: boss for emp, boss in pairs}

    def depth(name: str) -> int:
        d = 0
        while name in manager:
            name = manager[name]
            d += 1
        return d

    return abs(depth(pair[0]) - depth(pair[1]))

import java.util.*;

class Solution {
    int corporateLadder(String[] pair, String[][] pairs) {
        Map<String, String> manager = new HashMap<>();
        for (String[] p : pairs) manager.put(p[0], p[1]);
        return Math.abs(depth(pair[0], manager) - depth(pair[1], manager));
    }

    private int depth(String name, Map<String, String> manager) {
        int d = 0;
        while (manager.containsKey(name)) {
            name = manager.get(name);
            d++;
        }
        return d;
    }
}

class Solution {
public:
    int corporateLadder(vector<string>& pair, vector<vector<string>>& pairs) {
        unordered_map<string, string> manager;
        for (auto& p : pairs) manager[p[0]] = p[1];
        auto depth = [&](string name) {
            int d = 0;
            for (auto it = manager.find(name); it != manager.end(); it = manager.find(name)) {
                name = it->second;
                ++d;
            }
            return d;
        };
        return abs(depth(pair[0]) - depth(pair[1]));
    }
};
